  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(401, 15, 'Traumatologie', 'Poignet et radius distal', NULL, false, true, 'Votre examen clinique retrouve une pronation exagérée, quel traitement proposez-vous ? La RJ', '[{"l":"A","t":"Abstention therapeutique","c":false},{"l":"B","t":"Osteotomie d’allongement dur adius","c":false},{"l":"C","t":"Arthrodese du poignet","c":false},{"l":"D","t":"Osteotomie d ere orientation-Rotation","c":true},{"l":"E","t":"Osteotomie de raccourcissement","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(402, 15, 'Traumatologie', 'Poignet et radius distal', NULL, false, true, 'Quelle est la position de fonction en bilatéral pour cet enfant ? La RJ', '[{"l":"A","t":"Poignet0°en bilateral","c":false},{"l":"B","t":"Discrete pronation(20°)en bilateral","c":false},{"l":"C","t":"Supination de20°en bilateral","c":false},{"l":"D","t":"Pronation de 20° à droite + poignet à 0° à gauche","c":true},{"l":"E","t":"Pronation de20°a droite+supination de20°","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(403, 17, 'Traumatologie', 'Maladies luxantes de la hanche', NULL, false, true, 'La manouvre de BARLOW: La/Les RJ', '[{"l":"A","t":"Examine une hanche ala fois","c":true},{"l":"B","t":"Examine les deux hanches ala fois","c":false},{"l":"C","t":"Met en evidence parfois un ressaut","c":true},{"l":"D","t":"On percoit un ressaut qui peut etre franc ou discret","c":true},{"l":"E","t":"Ce sont des mouvements de prono supination du poignetdel’examinateur","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(404, 15, 'Traumatologie', 'Poignet et radius distal', NULL, false, true, 'Quelle est la tumeur des tissus mous du poignet la plus fréquente ?', '[{"l":"A","t":"Lipome","c":false},{"l":"B","t":"Angiome","c":false},{"l":"C","t":"Kyste sébacé","c":false},{"l":"D","t":"Kyste synovial","c":true},{"l":"E","t":"Kyste dermoïde","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(405, 15, 'Traumatologie', 'Poignet et radius distal', NULL, false, true, 'Parmi ces signes, quels sont ceux qui correspondent à une lésion du nerf radial ?', '[{"l":"A","t":"Anesthésie de la tabatière anatomique","c":true},{"l":"B","t":"Aspect en col de signe du poignet","c":true},{"l":"C","t":"Impossibilité de flexion de la main et des doigts","c":false},{"l":"D","t":"Possibilité de faire l’abduction rétropulsion du pouce","c":true},{"l":"E","t":"Toutes les réponses sont fausses.","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(406, 15, 'Traumatologie', 'Poignet et radius distal', NULL, false, true, 'Les signes neurologiques d’une main paralytique post traumatique du bras: La/Les RJ', '[{"l":"A","t":"Impossible de faire la flexion palmaire du poignet.","c":false},{"l":"B","t":"Impossible de faire l’extension metacarpo-phalangienne","c":true},{"l":"C","t":"Impossible de faire l’adduction du pouce.","c":false},{"l":"D","t":"Impossible de faire l’extension du pouce","c":true},{"l":"E","t":"Main en pronation.","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(407, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'La fracture de Poulteau colles est: (Cocher la ou les réponses justes):', '[{"l":"A","t":"La fracture la plus rare des fractures de l’extrémité inférieure du radius","c":false},{"l":"B","t":"Elle s’accompagne d’un déplacement antérieur de la glène radiale","c":false},{"l":"C","t":"La fracture est intra articulaire","c":false},{"l":"D","t":"Le traitement peut être orthopédique","c":false},{"l":"E","t":"La fracture fail suite à une chute sur la paume de la main en hyper extension","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(408, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Par rapport au traitement orthopédique, le traitement chirurgical à foyer ouvert d’une fracture de jambea les inconvénients suivants:', '[{"l":"A","t":"Nécessité de contrôles radiographiques répétés","c":false},{"l":"B","t":"Consolidation retardée","c":false},{"l":"C","t":"Risque de raideur","c":false},{"l":"D","t":"Risque infectieux","c":false},{"l":"E","t":"Risque thromboembolique Q 10. la fracture de l’extrémité inférieure du radius est: (cochez la ou les réponses justes)","c":false},{"l":"A","t":"survient le plus souvent chez le sujet jeun suite à un traumatisme violent","c":false},{"l":"B","t":"la moins fréquente des fractures de l’appareil locomoteur","c":false},{"l":"C","t":"peut perturber les rapports de l’articulation radio-cubitale","c":false},{"l":"D","t":"survient le plus souvent suite à un mécanisme indirect","c":false},{"l":"E","t":"traitement est toujours chirurgical Q 11. La fracture du scaphoïde carpien est (Cocher les réponses justes)","c":false},{"l":"A","t":"la fracture la plus rare des fractures du carpe","c":false},{"l":"B","t":"survient suite à un traumatisme direct","c":false},{"l":"C","t":"le traitement est toujours chirurgical","c":false},{"l":"D","t":"les fractures proximales peuvent évoluer vers l’ostéonécrose","c":false},{"l":"E","t":"la vascularisation du scaphoïde est à artère unique rétrograde Q 12. La fracture bimalléolaire par adduction est: (Cocher la ou les réponses justes)","c":false},{"l":"A","t":"la fracture bimalléolaire la plus fréquente","c":false},{"l":"B","t":"d- survient suite à un mécanisme en éversion","c":false},{"l":"C","t":"le trait sur la maliéole interne est vertical","c":false},{"l":"D","t":"pas de lésion de la syndesmose","c":false},{"l":"E","t":"le trait sur le péroné est sus tuberculaire","c":false}]'::jsonb, NULL, '["Rattrapage OTR promo 2019"]'::jsonb),
(409, 43, 'Traumatologie', 'Embolie et ischémie', NULL, false, true, 'Chez un polytraumatisé de 25 ans présentant depuis 3 jours une fracture du 1/3 supérieur du fémur immobilisée en traction, l’apparition brutale d’une agitation, d’une polypnée, de pétéchies conjonctivales et d’une baisse de la PaO2, doit faire évoquer en premier chef:', '[{"l":"A","t":"Une embolie pulmonaire","c":false},{"l":"B","t":"Une hémorragie interne","c":false},{"l":"C","t":"Un hématome intracrânien","c":false},{"l":"D","t":"Un pneumothorax traumatique méconnu","c":false},{"l":"E","t":"Une embolie graisseuse","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(410, 34, 'Traumatologie', 'Lombalgies et lombosciatalgies', NULL, true, true, 'Apres un accident de voiture important, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur au niveau de la hanche. L’abdomen est douloureux, ainsi que la région fessière. Des radiographies de face et de profil révèlent une luxation postérieure de la hanche et une fracture de l’os coxal. L’examen clinique doit rechercher avant tout une complication fréquente. Laquelle ?', '[{"l":"A","t":"Une paralysie sciatique","c":true},{"l":"B","t":"Une paralysie crurale","c":false},{"l":"C","t":"Une thrombose fémorale","c":false},{"l":"D","t":"Une ouverture cutanée postérieure","c":false},{"l":"E","t":"Un hématome de la fesse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(411, 34, 'Traumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'L’examen clinique doit rechercher avant tout une complication fréquente. Laquelle ?', '[{"l":"A","t":"une paralysie sciatique","c":true},{"l":"B","t":"une paralysie crurale","c":false},{"l":"C","t":"une thrombose fémorale","c":false},{"l":"D","t":"une ouverture cutanée postérieure","c":false},{"l":"E","t":"un hématome de la fesse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(412, 43, 'Traumatologie', 'Embolie et ischémie', NULL, false, true, 'L’ischémie aigue du membre ont:(Cocher la ou les réponses fausses)', '[{"l":"A","t":"Une urgence relative","c":true},{"l":"B","t":"Met en jeux seulement le pronostic fonctionnel","c":true},{"l":"C","t":"La désobstruction artérielle doit se faire avant la 12 heures.","c":true},{"l":"D","t":"Peut être due à une embolie sur artère pathologique","c":false},{"l":"E","t":"Responsable d’une acidose métabolique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(413, 43, 'Traumatologie', 'Embolie et ischémie', NULL, false, false, 'L’ischémie aigue du membre est: LA RJ', '[{"l":"A","t":"Une urgence relative","c":false},{"l":"B","t":"Met en jeux seulement le pronostic fonctionnel","c":false},{"l":"C","t":"La désobstruction artérielle doit se faire avant 12 heures","c":false},{"l":"D","t":"Peut être due à un embole sur artère pathologique","c":false},{"l":"E","t":"L’artériographie est indispensable pour le diagnostic positif","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(414, 43, 'Traumatologie', 'Embolie et ischémie', NULL, true, true, 'L’ischémie aigue du membre: cocher la ou les réponses justes', '[{"l":"A","t":"Urgence thérapeutique","c":true},{"l":"B","t":"La désobstruction peut se faire avant 12 heures","c":false},{"l":"C","t":"Le diagnostic clinique est basé sur l’artériographie","c":false},{"l":"D","t":"Le pronostic vital est mis en jeu","c":true},{"l":"E","t":"L’obstruction se fait toujours sur artère saine","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(415, 43, 'Traumatologie', 'Embolie et ischémie', NULL, true, true, 'L’ischémie aigue sur artère saine: cocher la ou les réponses fausses', '[{"l":"A","t":"Réalise le tableau d’ischémie sensitivomotrice","c":false},{"l":"B","t":"Les pouls contro- latéraux sont abolis","c":true},{"l":"C","t":"Présence de cardiopathie emboligène","c":true},{"l":"D","t":"Le début est progressif","c":false},{"l":"E","t":"Toutes les réponses sont justes","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(416, 7, 'Traumatologie', 'Embolie et ischémie', NULL, false, true, 'Concernant les complications de décubitus (choisissez la ou les réponses justes)', '[{"l":"A","t":"L’escarre et une complication tardive","c":false},{"l":"B","t":"Le traitement d’une escarre infectée se fait par une antibiothérapie locale.","c":false},{"l":"C","t":"La thrombose veineuse profonde peut être asymptomatique et être découverte devant un tableau d’embolie pulmonaire,","c":true},{"l":"D","t":"L’immobilisation augmente la stase bronchique, l’encombrement et l’infection","c":true},{"l":"E","t":"La prévention des infections urinaires se fait par le maintien d’un drainage continu (sondage intermittent)","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(417, 7, 'Traumatologie', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Concernant les complications cardio-vasculaires du décubitus, choisissez la ou les réponses fausses', '[{"l":"A","t":"le déconditionnement cardio-vasculaire est tardif","c":true},{"l":"B","t":"les thromboses veineuses profondes peuvent être prévenues par le port de bas de contention et la prescription d’héparine de bas poids moléculaire","c":false},{"l":"C","t":"les thromboses veineuses favorisées par la stase veineuse","c":false},{"l":"D","t":"la verticalisation progressive provoque une hypotension orthostatique","c":true},{"l":"E","t":"au niveau cardiaque il y a un déconditionnement à l’effort","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(418, 43, 'Traumatologie', 'Embolie et ischémie', NULL, false, true, 'Concernant la thrombose veineuse', '[{"l":"A","t":"Elle se manifeste par la douleur du mollet lors de la flexion plantaire du pied","c":false},{"l":"B","t":"l’échographie confirme le diagnostic","c":true},{"l":"C","t":"c’est une redistribution au profit des viscères et du cerveau entraînement et de désadaptation de la TA à l’orthostatique","c":false},{"l":"D","t":"la prévention se fait par lever précoce et position demie assise","c":true},{"l":"E","t":"l’hydratation suffisante fait partie des mesures préventives","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(419, 29, 'Traumatologie', 'Algoneurodystrophie', 'Cas clinique « Un homme de 70 ans hémiplégique gauche alité, présentant un œdème au pied et à la cheville gauche avec douleurs du mollet, le signe de Homans est', true, true, 'Quel diagnostic suspectez-vous ?', '[{"l":"A","t":"Syndrome douloureux régional complexe du pied et de la cheville gauche.","c":false},{"l":"B","t":"Thrombose veineuse profonde.","c":true},{"l":"C","t":"Embolie pulmonaire,","c":false},{"l":"D","t":"Entorse de la cheville.","c":false},{"l":"E","t":"POAN","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(420, 18, 'Traumatologie', 'Embolie et ischémie', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’ischémie aiguë des membres: La/Les RJ', '[{"l":"A","t":"Peut survenir sur des arteres saines","c":true},{"l":"B","t":"Le diagnostic nécessite un doppler du membre concerné","c":false},{"l":"C","t":"C’est une urgence chirurgicale","c":true},{"l":"D","t":"L’anesthesie cutanee est un signe de gravite","c":true},{"l":"E","t":"L’artériographie permet de localisé le niveau de l’obstruction","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(421, 18, 'Traumatologie', 'Embolie et ischémie', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’ischémie aiguë du membre: La/Les RF', '[{"l":"A","t":"Une urgence relative","c":true},{"l":"B","t":"Met en jeux seulement le pronostic fonctionnel","c":true},{"l":"C","t":"La désobstruction artérielle doit se faire avant la 12heures.","c":true},{"l":"D","t":"Peut etre due a une embolie sur artere pathologique","c":false},{"l":"E","t":"Responsable d’une acidose metabolique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(422, 18, 'Traumatologie', 'Embolie et ischémie', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’ischémie aiguë sur artère saine: La/Les RF', '[{"l":"A","t":"Realise le tableau d’ischemie sensitivomotrice","c":false},{"l":"B","t":"Les pouls contro-lateraux sont abolis","c":true},{"l":"C","t":"Presence de cardiopathie emboligene","c":false},{"l":"D","t":"Le debute st progressif","c":true},{"l":"E","t":"Toutes les reponses sont justes","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(423, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Un homme sous plâtre pour fracture de jambe datant de 4 jours ressent une violente douleur latérothoracique avec polypnée aiguë. La scintigraphie montre une lacune du lobe supérieur droit, la phlébographie montre une thrombose poplité Traitement?', '[{"l":"A","t":"Ostéosynthèse de la fracture pour éviter la mobilisation du caillot","c":false},{"l":"B","t":"Héparinothérapie préventive","c":false},{"l":"C","t":"Fibrinolytique","c":false},{"l":"D","t":"Héparinothérapie à dose anti-coagulante","c":true},{"l":"E","t":"Interruption partielle de la veine cave inférieure","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(424, 18, 'Traumatologie', 'Amputations des membres', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La constatation d’une fièvre progressivement ascendante dans les suites d’une intervention orthopédique des membres inférieurs complétée par un plâtre, doit faire rechercher la ou les complication(s) suivante(s):', '[{"l":"A","t":"Une thrombose veineuse profonde","c":true},{"l":"B","t":"Une suppuration de la plaie opératoire","c":true},{"l":"C","t":"Un syndrome de la loge","c":false},{"l":"D","t":"Une infection urinaire","c":true},{"l":"E","t":"Une hypovolémie","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(425, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Chez un polytraumatisé de 25 ans présentant depuis 3 jours une fracture du 1/3 supérieur du fémur immobilisée en traction, l’apparition brutale d’une agitation d’une polypnée, de pétéchies conjonctivales et d’une baisse de la Pa 02, évoque en premier:', '[{"l":"A","t":"Une embolie pulmonaire","c":false},{"l":"B","t":"Une hémorragie interne","c":false},{"l":"C","t":"Un hématome intracrânien","c":false},{"l":"D","t":"Un pneumothorax traumatique méconnu","c":false},{"l":"E","t":"Une embolie graisseuse","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(426, 18, 'Traumatologie', 'Embolie et ischémie', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Chez un homme de 69 ans, 48 heures après une prothèse totale de hanche, on constate: dyspnée, douleur thoracique Quel examen réalisé en urgence vous permettra d’éliminer le diagnostic d’embolie pulmonaire, s’il est normal ?', '[{"l":"A","t":"Electrocardiogramme","c":false},{"l":"B","t":"Phlébographie des membres inférieurs","c":false},{"l":"C","t":"Radiographie thoracique face et profil","c":false},{"l":"D","t":"Scintigraphie pulmonaire de perfusion sous 4 incidences","c":true},{"l":"E","t":"Rhéopléthysmographie d’impédance","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(427, 18, 'Traumatologie', 'Embolie et ischémie', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Devant une disjonction traumatique de la symphyse pubienne vue en urgence, indiquez la complication que vous devez particulièrement redouter:', '[{"l":"A","t":"Luxation sacro-iliaque","c":false},{"l":"B","t":"Paralysie obturatrice","c":false},{"l":"C","t":"Hémorragie intra-péritonéale","c":false},{"l":"D","t":"Embolie graisseuse","c":false},{"l":"E","t":"Déchirure de l’urèthre","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(428, 18, 'Traumatologie', 'Embolie et ischémie', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'A propos de l’embolie graisseuse:(cochez les réponses justes)', '[{"l":"A","t":"Se voit 24 à 72 heures après le traumatisme","c":true},{"l":"B","t":"Se manifeste par une détresse respiratoire aigüe","c":true},{"l":"C","t":"Les pétéchies cutanées et conjonctivales en sont le maître symptôme","c":true},{"l":"D","t":"Un état confusionnel est toujours présent","c":false},{"l":"E","t":"Peut s’accompagner d’insuffisance rénale aigue","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(429, 18, 'Traumatologie', 'Embolie et ischémie', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Parmi les signes para cliniques suivants, lequel n’est pas vrai en cas embolie graisseuse:', '[{"l":"A","t":"Anémie","c":false},{"l":"B","t":"Hyperleucocytose","c":true},{"l":"C","t":"Thrombopénie","c":false},{"l":"D","t":"Images en ?tempête de neige” dans les 2 champs pulmonaires sur le télé thorax","c":false},{"l":"E","t":"Les métabolismes protidique et lipidique ne sont pas perturbés","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(430, 18, 'Traumatologie', 'Embolie et ischémie', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’ischémie aigue du membre: La RJ', '[{"l":"A","t":"Peut être une urgence relative","c":false},{"l":"B","t":"Peut mettre en jeux seulement le pronostic fonctionnel","c":false},{"l":"C","t":"La désobstruction artérielle doit se faire avant la 12 heures","c":false},{"l":"D","t":"Peut être due à une embolie sur artère pathologique","c":true},{"l":"E","t":"L’artériographie est indispensable pour le diagnostic positif","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(431, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'Traumatisme par mécanisme « de tableau de bords » peut entrainer: A Une luxation antérieure de la hanche', '[{"l":"B","t":"Une fracture du poignet","c":false},{"l":"C","t":"Une fracture de la rotule","c":true},{"l":"D","t":"Une fracture-luxation postérieure de la hanche","c":true},{"l":"E","t":"Une lésion ligamentaire du genou","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(432, 37, 'Traumatologie', 'Genou', NULL, false, true, 'La fracture du plateau tibial Externe est: cochez la ou les réponses justes)', '[{"l":"A","t":"La fracture la plus fréquente des fractures des plateaux tibiaux","c":true},{"l":"B","t":"On ne trouve jamais d’enfoncement fracturaire","c":false},{"l":"C","t":"Le traitement est le plus souvent chirurgical","c":true},{"l":"D","t":"Le mécanisme est toujours indirect","c":false},{"l":"E","t":"Elle est pourvoyeuse de raideur de genou","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(433, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'Quelle complication ne survient JAMAIS après fracture de la rotule ?', '[{"l":"A","t":"Arthrose fémoro-patellaire","c":false},{"l":"B","t":"Algodystrophie du membre inférieur","c":false},{"l":"C","t":"Raideur du genou avec flexion réduite à 10°","c":false},{"l":"D","t":"Pseudarthrose rendant la marche impossible par défaut de verrouillage du genou","c":false},{"l":"E","t":"Recurvatum sévère du genou","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(434, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'Traumatisme par mécanisme « de tableau de bords » peut entrainer: A Une luxation antérieure de la hanche', '[{"l":"B","t":"Une fracture du poignet","c":false},{"l":"C","t":"Une fracture de la rotule","c":true},{"l":"D","t":"Une fracture-luxation postérieure de la banche","c":true},{"l":"E","t":"Une lésion ligamentaire du genou","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(435, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'Une femme de 50 ans est traitée par réduction orthopédique et plâtre cruro-pédieux pour une fracture diaphysaire fermée des 2 os de la jambe. Quelles sont au 10ème jour après du traitement, les deux complications les plus fréquentes ?', '[{"l":"A","t":"Epanchement intra-articulaire du genou.","c":false},{"l":"B","t":"Une phlébite sous plâtre.","c":true},{"l":"C","t":"Suppuration du foyer de fracture.","c":false},{"l":"D","t":"Ouverture secondaire du foyer de fracture.","c":false},{"l":"E","t":"Déplacement secondaire sous plâtre.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(436, 36, 'Traumatologie', 'Genou', NULL, false, true, 'Un liquide articulaire issu d’une ponction du genou chez un spondylarthrique possède les caractéristiques suivantes:', '[{"l":"A","t":"Un taux de protides supérieur à 30g/L","c":true},{"l":"B","t":"Un nombre de leucocytes compris entre 2000 et 50000 éléments/mm3","c":true},{"l":"C","t":"Un nombre de leucocyte compris entre 500 et 1000 éléments/mm3","c":false},{"l":"D","t":"Septique","c":false},{"l":"E","t":"Consonne de micro cristaux d’urate de sodium","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(437, 36, 'Traumatologie', 'Genou', NULL, false, true, 'L’aplasie segmentaire d’un membre au niveau du bras avec présence de poignée est aussi appelé: (cocher la réponse juste)', '[{"l":"A","t":"une péromelie","c":true},{"l":"B","t":"une phocomélie","c":true},{"l":"C","t":"une Amélie","c":true},{"l":"D","t":"main bote cubitale","c":false},{"l":"E","t":"main bote radiale","c":false},{"l":"A","t":"un genu recurvatum congénital","c":true},{"l":"B","t":"un genou malformé","c":true},{"l":"C","t":"une arthrite de genou","c":true},{"l":"D","t":"une maladie d’Osgood-Schlatter","c":false},{"l":"E","t":"une ostéochondrite disséquante du genou","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(438, 36, 'Traumatologie', 'Genou', 'Cas clinique: Un enfant de 4 ans, quelques heures après un traumatisme bénin du genou, accuse une douleur lancinante de l’extrémité inférieure du fémur associée à une élévation thermique à 39°5.', true, true, 'Quel(s) signe(s) clinique(s) recherchez-vous ?', '[{"l":"A","t":"Impotence fonctionnelle","c":true},{"l":"B","t":"Un flexum irréductible du genou","c":false},{"l":"C","t":"Une douleur localisée sur le condyle interne","c":false},{"l":"D","t":"Une douleur métaphysaire circulaire et transfixiante","c":false},{"l":"E","t":"La présence d’adénopathies inguinales","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(439, 36, 'Traumatologie', 'Genou', 'Cas clinique: Un enfant de 4 ans, quelques heures après un traumatisme bénin du genou, accuse une douleur lancinante de l’extrémité inférieure du fémur associée à une élévation thermique à 39°5.', false, true, 'Quels sont les examens paracliniques de première intention ?', '[{"l":"A","t":"Une ponction articulaire avec étude ctyo- bactériologique et chimique","c":false},{"l":"B","t":"Une radiographie Standard du genou en charge de face et de profil","c":true},{"l":"C","t":"Une TDM du genou","c":false},{"l":"D","t":"Une radio télémétrie en charge des membres inférieurs","c":false},{"l":"E","t":"Une incidence de Schuss","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(440, 3, 'Traumatologie', 'Principe de base en médecine physique et réadaptation', 'Cas clinique: Un enfant de 4 ans, quelques heures après un traumatisme bénin du genou, accuse une douleur lancinante de l’extrémité inférieure du fémur associée à une élévation thermique à 39°5.', false, true, 'Que prescrivez-vous pour soulager la douleur chez cette patiente qui se présente avec un épanchement du genou ?', '[{"l":"A","t":"Les anti-inflammatoires non stéroïdiens par voie orale.","c":true},{"l":"B","t":"Les anti-inflammatoires non stéroïdiens par voie locale,","c":true},{"l":"C","t":"Une infiltration de corticoïde,","c":true},{"l":"D","t":"Une physiothérapie a type d’infrarouge et d’ultrasons,","c":false},{"l":"E","t":"Une canne simple du côté de l’épanchement","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(441, 36, 'Traumatologie', 'Genou', 'Cas clinique: Un enfant de 4 ans, quelques heures après un traumatisme bénin du genou, accuse une douleur lancinante de l’extrémité inférieure du fémur associée à une élévation thermique à 39°5.', false, false, 'Pour pouvoir s’accroupir, il faut: La RF', '[{"l":"A","t":"Une bonne mobilité de la rotule.","c":false},{"l":"B","t":"120° de flexion du genou.","c":false},{"l":"C","t":"Une rétraction du cul de sac sous quadricipital.","c":false},{"l":"D","t":"Une certaine élasticité tendineuse.","c":false},{"l":"E","t":"Pas d’adhérences articulaires","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(442, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La fracture des plateaux tibiaux peut être: La/Les RJ', '[{"l":"A","t":"Responsable le plus souvent d’un mécanisme par compressionaxiale.","c":false},{"l":"B","t":"Compliquee de raideur et d’arthrose articulaire","c":true},{"l":"C","t":"Responsable d’une fracture enfoncement du plateau tibiale xterne","c":true},{"l":"D","t":"Due le plus souvent aun choc direct lateral","c":true},{"l":"E","t":"Toutes les reponses sont justes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(443, 37, 'Traumatologie', 'Genou', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La fracture du plateau tibial Externe: La/Les RJ', '[{"l":"A","t":"La fracture la plus fréquente des fractures des plateauxtibiaux","c":true},{"l":"B","t":"Onne trouve jamais d’enfoncement fracturaire","c":false},{"l":"C","t":"Le traitement est le plus souvent chirurgical","c":true},{"l":"D","t":"Lemécanismeesttoujoursindirect","c":false},{"l":"E","t":"Elle est pourvoyeuse de raideur de genou","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(444, 18, 'Traumatologie', 'Amputations des membres', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Le traitement de choix de la fracture de la patella est: La/Les RJ', '[{"l":"A","t":"Vissage","c":false},{"l":"B","t":"Embrochage simple","c":false},{"l":"C","t":"Haubanage","c":true},{"l":"D","t":"Genouillere platree pendant6semaines","c":false},{"l":"E","t":"Plaque vissee","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","Annales classées","EMD OTR section A","EMD (section A) PROMO 2017"]'::jsonb),
(445, 18, 'Traumatologie', 'Amputations des membres', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La fracture sagittale de la rotule est: La/Les RJ', '[{"l":"A","t":"Une fracture articulaire","c":true},{"l":"B","t":"Une fracture qui rompt l’appareil extenseur","c":false},{"l":"C","t":"Confondue avec une patella bipartita","c":true},{"l":"D","t":"Traitee par une simple immobilisation platree","c":true},{"l":"E","t":"Traitee parfois par un cerclage equatorial","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(446, 18, 'Traumatologie', 'Genou', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’atteinte du genou chez le nouveau-né et le nourrisson peut être due à:', '[{"l":"A","t":"Un genu recurvatum congenital","c":true},{"l":"B","t":"Un genou malforme","c":true},{"l":"C","t":"Une arthrite de genou","c":true},{"l":"D","t":"Une maladie d’osgood-sc hla tter","c":false},{"l":"E","t":"Une osteochondrite dissequante du genou","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(447, 18, 'Traumatologie', 'Genou', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Quels sont les examens paracliniques de 1ère intention ?', '[{"l":"A","t":"Une ponction articulaire avec étude ctyo- bacteriologique et chimique","c":false},{"l":"B","t":"Une radiographie Standard du genou en charge defaceetdeprofil","c":true},{"l":"C","t":"Une tdm du genou","c":false},{"l":"D","t":"Une radio telemetrie en charge des membres inf","c":false},{"l":"E","t":"Une incidence des chuss","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(448, 30, 'Traumatologie', 'Tumeurs osseuses (bénignes et malignes)', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’Hygroma est:', '[{"l":"A","t":"Toute tumeur des tissus mous de la face d’extension d’une articulation","c":false},{"l":"B","t":"Une tumeur osseuse de la rotule","c":false},{"l":"C","t":"Une tumeur kystique du creux poplité","c":false},{"l":"D","t":"Une tumeur kystique de la face d’extension du coude ou du genou","c":true},{"l":"E","t":"L’autre nom de l’épine olécrânienne","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(449, 36, 'Traumatologie', 'Genou', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Concernant la rupture du ligament croisé antérieur du genou: (cochez les réponses justes)', '[{"l":"A","t":"Est due principalement à un mécanisme en flexion valgus rotation externe","c":false},{"l":"B","t":"Provoque une translation sibiale postérieure","c":false},{"l":"C","t":"Provoque une translation tale antérieure","c":false},{"l":"D","t":"L’hémarthrose est un signe pathognomonique","c":false},{"l":"E","t":"L’IRM est l’examen la plus performant pour son diagnostique","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(450, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, false, true, 'La nécrose de la tête fémorale après fracture cervicale vraie du fémur est due à:', '[{"l":"A","t":"Une mauvaise immobilisation","c":false},{"l":"B","t":"Une pseudarthrose","c":false},{"l":"C","t":"Une ischémie par lésion des branches de l’artère circonflexe postérieure","c":true},{"l":"D","t":"Une infection postopératoire","c":false},{"l":"E","t":"Le siège intra ou extra capsulaire du trait de fracture","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022","Banque de QCM OTR","Banque de QCM OTR p.12"]'::jsonb),
(451, 34, 'Traumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Une fracture de la diaphyse fémorale au tiers moyen avant tout traitement:', '[{"l":"A","t":"Se présente avec une déformation en crosse de la cuisse","c":true},{"l":"B","t":"Se présente avec une rotation externe du membre inférieur","c":true},{"l":"C","t":"Peut entrainer par elle-même un choc hémorragique","c":true},{"l":"D","t":"Entrainera souvent une paralyse sciatique","c":false},{"l":"E","t":"Peut se compliquer d’embolie graisseuse","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(452, 31, 'Traumatologie', 'Fémur', NULL, false, true, 'Les fractures de l’extrémité inférieure du fémur (cocher la ou les réponses justes)', '[{"l":"A","t":"sont plus fréquentes chez le sujet jeune","c":true},{"l":"B","t":"ne se voient jamais chez le sujet âgé","c":false},{"l":"C","t":"leur traitement chirurgical n’est jamais difficile","c":false},{"l":"D","t":"peuvent s’associer à d’autres lésions de l’appareil locomoteur","c":true},{"l":"E","t":"peuvent être articulaires ou extra articulaires","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(453, 31, 'Traumatologie', 'Fémur', NULL, false, true, 'Dans la fracture de la diaphyse fémorale chez l’adulte (cocher la ou les réponses justes)', '[{"l":"A","t":"le traitement peut être orthopédique","c":false},{"l":"B","t":"le risque de syndrome d’embolie graisseuse est important","c":true},{"l":"C","t":"le pronostic vital peut être mis en jeu par choc hémorragique","c":true},{"l":"D","t":"une fracture associée du col fémoral homolatéral est à rechercher avec attention","c":true},{"l":"E","t":"on peut proposer la traction trans-osseuse comme traitement chez le sujet jeune","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(454, 31, 'Traumatologie', 'Fémur', NULL, true, true, 'Dans la fracture de la diaphyse fémorale chez l’adulte: cocher la ou les réponses juste(s)', '[{"l":"A","t":"le risque de syndrome d’embolie graisseuse est important.","c":true},{"l":"B","t":"Le pronostic vital peut être mis en jeu par choc hémorragique.","c":true},{"l":"C","t":"une fracture associée du col fémoral homolatéral est à rechercher avec attention.","c":true},{"l":"D","t":"On peut proposer la traction trans-osseuse comme traitement chez le sujet Jeune.","c":false},{"l":"E","t":"Le traitement orthopédique est souvent indiqué chez l’adulte jeune.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(455, 31, 'Traumatologie', 'Fémur', NULL, false, true, 'Le diagnostic d’éctromélie longitudinale latérale est posé quand: (cochez la ou les réponses justes)', '[{"l":"A","t":"Il y a une agénésie du fémur.","c":false},{"l":"B","t":"L’ulna est hypoplasique","c":false},{"l":"C","t":"Il y a une duplication du pouce","c":false},{"l":"D","t":"Il y a une agénésie du péroné","c":true},{"l":"E","t":"Le péroné est dévié en latéral","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(456, 5, 'Traumatologie', 'Non classé', NULL, false, true, 'Parmi les facteurs suivants, le (les) quel (s) peut (peuvent) être à l’origine d’un genu valgum:', '[{"l":"A","t":"Fracture de la diaphyse fémorale","c":false},{"l":"B","t":"Ostéomyélite de l’extrémité supérieure du tibia.","c":true},{"l":"C","t":"Luxation récidivante de la rotule.","c":true},{"l":"D","t":"Spina bifida L4, L5.","c":true},{"l":"E","t":"Tibia vara ou maladie de Blount","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(457, 31, 'Traumatologie', 'Fémur', NULL, false, true, 'Quels sont les principaux objectifs d’une prise en charge rééducative après une fracture consolidée du fémur ? (Réponses justes)', '[{"l":"A","t":"la récupération des amplitudes articulaires","c":true},{"l":"B","t":"le renforcement musculaire","c":true},{"l":"C","t":"le travail proprioceptifs","c":true},{"l":"D","t":"l’immobilisation jusqu’à disparition complète des douleurs","c":false},{"l":"E","t":"la mise en charge progressive par la diminution de niveau d’immersion en balnéothérapie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(458, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La fracture de la diaphyse du fémur: La/Les RJ', '[{"l":"A","t":"Est une fracture frequente chez les ujet jeune.","c":true},{"l":"B","t":"Son traitement impose la mise en place d’une prothèse.","c":false},{"l":"C","t":"Enclouage centromedullaire est souvent indique.","c":true},{"l":"D","t":"Traction trans-tibiale est un traitement de choix.","c":false},{"l":"E","t":"Ostéosynthèse par plaque vissée peux être indiquée.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(459, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Dans la fracture de la diaphyse fémorale chez l’adulte: La/Les RJ', '[{"l":"A","t":"Le traitement peut etre orthopedique","c":false},{"l":"B","t":"Le risque de syndrome d’embolie graisseuse est important","c":true},{"l":"C","t":"Le pronostic vital peut être mis en jeu par choc hémorragique","c":true},{"l":"D","t":"Une fracture associée du col fémoral homolatéral est a rechercher avec attention","c":true},{"l":"E","t":"On peut proposer la traction trans-osseuse comme traitement chez les ujet jeune","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(460, 18, 'Traumatologie', 'Fémur', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Le diagnostic d’éctromélie longitudinale latérale est posé quand: La/Les RJ', '[{"l":"A","t":"Ilya une agenesie du femur.","c":false},{"l":"B","t":"L’ulna est hypoplasique","c":false},{"l":"C","t":"Ilya une duplication du pouce","c":false},{"l":"D","t":"Ilya une agenesie du perone","c":true},{"l":"E","t":"Le perone est devie en lateral","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(461, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Quelle est ou quelles sont l’ (ou les) artère(s) dont la rupture associée à un foyer de fracture crée(nt) un risque ischémique majeur ?', '[{"l":"A","t":"L’artère iliaque externe","c":true},{"l":"B","t":"L’artère fémorale commune","c":true},{"l":"C","t":"L’artère fémorale superficielle","c":false},{"l":"D","t":"L’artère poplitée","c":true},{"l":"E","t":"L’artère axilaire basse","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(462, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Parmi les signe radiologiques suivants, un seul n’est pas un signe de coxarthose. Lequel ?', '[{"l":"A","t":"Pincement de l’interligne coxo-fémoral","c":false},{"l":"B","t":"Présence d’ostéophytes","c":false},{"l":"C","t":"Présence de géodes","c":false},{"l":"D","t":"Existence d’une déminéralisation sous-chondrale","c":true},{"l":"E","t":"Excentration de la tête fémorale","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(463, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La nécrose de la tête fémorale après fracture du col du fémur:', '[{"l":"A","t":"Est favorisée par un trait de fracture intra-articulaire","c":true},{"l":"B","t":"Est favorisée par une fracture à grand déplacement","c":true},{"l":"C","t":"Peut être diagnostiquée par scintigraphie","c":true},{"l":"D","t":"Se manifeste habituellement trois mois après la fracture","c":false},{"l":"E","t":"Doit être traitée le plus souvent par prothèse si telle est mal tolérée","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(464, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Une fracture de la diaphyse fémorale au tiers moyen avant tout traitement:', '[{"l":"A","t":"Se présente avec une déformation en crosse de la cuisse","c":true},{"l":"B","t":"Se présente avec une rotation externe du membre inférieur","c":true},{"l":"C","t":"Peut entrainer par elle-même un choc hémorragique","c":true},{"l":"D","t":"Entrainera souvent une paralysie sciatique","c":false},{"l":"E","t":"Peut se compliquer d’embolie graisseuse","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(465, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Une fracture du fémur per-trochantérienne:', '[{"l":"A","t":"Entraine 50% de nécroses et pseudarthroses de la tête fémorale","c":false},{"l":"B","t":"Se traduit cliniquement par un membre inférieur en abduction et rotation interne","c":false},{"l":"C","t":"Se traite par une ostéosynthèse","c":true},{"l":"D","t":"Entraine à 3 mois, chez le vieillard, une mortalité moyenne de 15 à 20%","c":true},{"l":"E","t":"Est opérée en extrême urgence","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(466, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Une luxation - fracture du cotyle:', '[{"l":"A","t":"Est, par ordre de fréquence, ischiatique, obturatrice, pubienne et iliaque","c":false},{"l":"B","t":"Sa principale complication immédiate est une fracture trans-cervicale du fémur","c":false},{"l":"C","t":"S’accompagne plus souvent d’une contusion du nerf sciatique que d’une contusion du crural","c":true},{"l":"D","t":"La rupture de l’artère ischiatique est à l’origine de la nécrose de la tête fémorale","c":false},{"l":"E","t":"Sa réduction doit se faire en extrême urgence","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(467, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Les fractures de la diaphyse du fémur: La/Les RJ', '[{"l":"A","t":"Est une fracture fréquente chez le sujet jeune","c":true},{"l":"B","t":"Son traitement impose la mise en place d’une prothèse.","c":false},{"l":"C","t":"Enclouage centromédullaire est souvent indique.","c":true},{"l":"D","t":"Traction trans-tibiale est un traitement de choix","c":false},{"l":"E","t":"Ostéosynthèse par plaque visse est une indication habituelle pour les fractures du fémur","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(468, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'La BURST fracture au rachis dorso-lombaire:', '[{"l":"A","t":"Est un type A2 de MAGERL","c":false},{"l":"B","t":"Entraine une instabilité mixte","c":false},{"l":"C","t":"Peux donner des lésions neurologiques par recul du mur postérieur","c":true},{"l":"D","t":"Est due à un mécanisme en compression","c":true},{"l":"E","t":"Nécessite toujours une laminectomie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(469, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'La BURST fracture au rachis dorso-lombaire:', '[{"l":"A","t":"Est un type A2 de MAGERL","c":false},{"l":"B","t":"Entraine une instabilité osseuse","c":true},{"l":"C","t":"Peux donner des lésions neurologiques par recul du mur postérieur","c":true},{"l":"D","t":"Est due à un mécanisme en compression","c":true},{"l":"E","t":"Nécessite toujours une laminectomie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(470, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'L’entorse grave du rachis cervical:', '[{"l":"A","t":"Entraine un antélisthésis","c":true},{"l":"B","t":"Est diagnostiquée par des clichés dynamiques","c":true},{"l":"C","t":"Peux donner une radio normale","c":true},{"l":"D","t":"La lésion ligamentaire provoquée est irréversible","c":true},{"l":"E","t":"Peux être traité orthopédiquement","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(471, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'L’entorse grave du rachis cervical:', '[{"l":"A","t":"Entraine une atteinte du segment vertébral moyen","c":false},{"l":"B","t":"Est diagnostiquée par des clichés dynamiques","c":true},{"l":"C","t":"Est diagnostiquée par une radio du rachis bouche ouverte","c":false},{"l":"D","t":"Nécessite une arthrodèse","c":true},{"l":"E","t":"Peux être traitée par un collier cervical","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(472, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'Indiquez parmi les suivantes la ou les proposition(s) exacte(s): une entorse grave du rachis cervical inférieur peut entrainer:', '[{"l":"A","t":"Une compression médullaire","c":true},{"l":"B","t":"Une névralgie cervico brachiale","c":true},{"l":"C","t":"Un glissement progressif d’une vertèbre sur la vertèbre sous-jacente","c":true},{"l":"D","t":"Une subluxation des apophyses articulaires","c":true},{"l":"E","t":"Des troubles bulbaires","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Banque de QCM OTR","Banque de QCM OTR p.15"]'::jsonb),
(473, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'Indiquez parmi les suivantes la réponse fausse: Une entorse grave du rachis cervical Inferieur peut entrainer:', '[{"l":"A","t":"Une compression médullaire","c":false},{"l":"B","t":"Une névralgie cervicobrachiale","c":false},{"l":"C","t":"Un glissement progressif d’une vertèbre sur la vertèbre sous-jacente","c":false},{"l":"D","t":"Une subluxation des apophyses articulaires","c":false},{"l":"E","t":"Des troubles bulbaires","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(474, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'Une fracture vertébrale d’origine tuberculeuse:', '[{"l":"A","t":"Peut siéger au rachis cervical","c":true},{"l":"B","t":"Ne touche pas le mur postérieur de la vertèbre","c":false},{"l":"C","t":"Peut être associée à une atteinte discale","c":true},{"l":"D","t":"Peut être associée à une épidurite","c":true},{"l":"E","t":"Peut être associée à un abcès paravertébral","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(475, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'Le syndrome algodystrophique est une pathologie qui touche: (citez la réponse juste)', '[{"l":"A","t":"Uniquement le rachis cervical.","c":false},{"l":"B","t":"Plus particulièrement les extrémités des membres.","c":true},{"l":"C","t":"La femme en période de post ménopause.","c":false},{"l":"D","t":"Les articulations du genou.","c":false},{"l":"E","t":"Les articulations sacro-iliaques","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(476, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'L’entorse grave du rachis cervical peut:', '[{"l":"A","t":"Entrainer un anthelestesis","c":true},{"l":"B","t":"Etre diagnostiquer par des cliches dynamiques.","c":true},{"l":"C","t":"Donner une radio normale","c":true},{"l":"D","t":"Provoquer une lesion ligamentaire irreversible","c":true},{"l":"E","t":"Etre traite orthopediquement","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(477, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'Une entorse grave du rachis cervical inférieur peut entraîner: La/Les RJ', '[{"l":"A","t":"Une compression medullaire","c":true},{"l":"B","t":"Une nevralgie cervicobrachiale","c":true},{"l":"C","t":"Un glissement progressif d’une vertèbre sur la vertèbresous-jacente","c":true},{"l":"D","t":"Une subluxation des apophyses articulaires","c":true},{"l":"E","t":"Des troubles bulbaires","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(478, 24, 'Traumatologie', 'Rachis traumatique', NULL, false, true, 'Le syndrome algodystrophique est une pathologie qui touche: La RJ', '[{"l":"A","t":"Uniquement le rachis cervical.","c":false},{"l":"B","t":"Plus particulierement lese xtremi tes des membres.","c":true},{"l":"C","t":"La femme en periode de post menopause.","c":false},{"l":"D","t":"Les articulations du genou.","c":false},{"l":"E","t":"Les articulations sac ro-iliaques","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(479, 2, 'Traumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'La polyarthrite rhumatoïde épargne généralement: (cochez la ou les réponses justes)', '[{"l":"A","t":"le rachis cervical","c":false},{"l":"B","t":"b – le rachis lombaire","c":true},{"l":"C","t":"c – le rachis dorsal","c":true},{"l":"D","t":"d – l’articulation temporo-mandibulaires","c":false},{"l":"E","t":"e – les sacro-iliaques","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(480, 18, 'Traumatologie', 'Amputations des membres', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’entorse grave du rachis cervical peut: La/Les RJ', '[{"l":"A","t":"Entraîner un anthélestesis","c":true},{"l":"B","t":"Être diagnostiquer par des clichés dynamiques.","c":true},{"l":"C","t":"Donner une radio normale","c":true},{"l":"D","t":"Provoquer une lésion ligamentaire irreversible","c":true},{"l":"E","t":"Être traité orthopédiquement","c":false}]'::jsonb, NULL, '["EMD OTR section A"]'::jsonb),
(481, 18, 'Traumatologie', 'Amputations des membres', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’entorse grave du rachis cervical: La/Les RJ', '[{"l":"A","t":"Entraine un anthélestesis","c":true},{"l":"B","t":"Peut-être diagnostiquée par des clichés dynamiques.","c":true},{"l":"C","t":"Peut donner une radio normale","c":true},{"l":"D","t":"La lésion ligamentaire provoquée est irréversible","c":true},{"l":"E","t":"Peut être traité orthopédiquement","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(482, 24, 'Traumatologie', 'Rachis traumatique', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'L’entorse grave du rachis cervical: (cochez les réponses justes)', '[{"l":"A","t":"La radiologie peut être normale","c":false},{"l":"B","t":"Elle est objectivée sur une radio dynamique","c":false},{"l":"C","t":"Elle touche le segment mobile rachidien","c":false},{"l":"D","t":"Elle touche le segment vertébral moyen","c":false},{"l":"E","t":"Peut être traitée orthopédiquement","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(483, 26, 'Traumatologie', 'Bassin et cotyle', NULL, true, true, 'Le premier geste thérapeutique sur les lésions osseuse est:', '[{"l":"A","t":"La réduction de la luxation","c":true},{"l":"B","t":"L’ostéosynthèse du cotyle","c":false},{"l":"C","t":"La mise en extension continue","c":false},{"l":"D","t":"La mise en place d’une prothèse de hanche","c":false},{"l":"E","t":"Immobilisation plâtrée","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022","Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(484, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', NULL, false, true, 'Parmi ces lésions associées que sont les plus probables dans la luxation postérieure de la hanche: (la ou les réponses justes)', '[{"l":"A","t":"fracture de la paroi postérieure du cotyle","c":true},{"l":"B","t":"fracture de la tête fémorale","c":true},{"l":"C","t":"disjonction de la symphyse pubienne","c":false},{"l":"D","t":"fracture de la cinquième vertèbre lombaire","c":false},{"l":"E","t":"fracture de la rotule","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(485, 34, 'Traumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Dans la luxation postérieure de la hanche (cochez la ou les réponses justes):', '[{"l":"A","t":"Le membre se met en abduction rotation interne","c":false},{"l":"B","t":"Peut s’associer à une fracture de la paroi postérieure de l’acétabulum","c":true},{"l":"C","t":"Peut se compliquer d’une lésion du nerf sciatique","c":true},{"l":"D","t":"Le mécanisme du tableau de bord est le plus habituel","c":true},{"l":"E","t":"La femme âgée est plus souvent concernée","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(486, 34, 'Traumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Dans la luxation postérieure de la hanche: (cochez les réponses fausses):', '[{"l":"A","t":"Le membre se met en abduction rotation interne et raccourcissement.","c":true},{"l":"B","t":"Peut s’associer à une fracture de la paroi postérieure de l’acétabulum.","c":false},{"l":"C","t":"Peut se compliquer d’une lésion du nerf sciatique.","c":false},{"l":"D","t":"Le mécanisme du tableau de bord et le plus habituel.","c":false},{"l":"E","t":"La femme âgée est plus souvent concernée.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(487, 17, 'Traumatologie', 'Bassin et cotyle', NULL, false, true, 'Sur une radiographie du bassin de face strict, en cas de LCH, on analyse:', '[{"l":"A","t":"Un retard d’apparition des noyaux d’ossification","c":true},{"l":"B","t":"Un angle acétabulaire augmentée témoignant de la luxation de hanche","c":false},{"l":"C","t":"La projection des noyaux épiphysaires fémoraux dans le cadrant inféro-externe témoigne de la luxation de hanche","c":true},{"l":"D","t":"Le cintre cervico–obturateur n’est jamais rompu","c":false},{"l":"E","t":"La position de la ligne de Putti par rapport au côtyle avec des noyaux d’ossifications des têtes fémorales visibles","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(488, 17, 'Traumatologie', 'Bassin et cotyle', NULL, true, true, 'Devant une hanche douloureuse plusieurs diagnostic peuvent être évoqué sauf un lequel:', '[{"l":"A","t":"L’ostéo-chondrite de hanche","c":false},{"l":"B","t":"Ostéo-arthrite de hanche","c":false},{"l":"C","t":"Une tumeur osseuse","c":false},{"l":"D","t":"Luxation congénitale de la hanche","c":true},{"l":"E","t":"Fracture du bassin","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(489, 26, 'Traumatologie', 'Bassin et cotyle', NULL, false, true, 'Dans la luxation postérieure de la hanche: Les RF', '[{"l":"A","t":"Lemembresemeten abduction rotation interneet raccourcissement.","c":true},{"l":"B","t":"Peut s’associer à une fracture de la paroi postérieuredel’acétabulum.","c":false},{"l":"C","t":"Peutsecompliquerd’unelésiondunerfsciatique.","c":false},{"l":"D","t":"Lemécanismedutableaudebordestleplushabituel.","c":false},{"l":"E","t":"La femme agee est plus souvent concernee.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(490, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Une ostéoporose secondaire est suspectée devant: La/Les RJ', '[{"l":"A","t":"Une fracture par fragilité osseuse de l’extrémité superieure du femur chez un homme de43ans","c":true},{"l":"B","t":"Des fractures iteratives chez une femme de70ans","c":false},{"l":"C","t":"Unefracturedel’extrémitéinférieurduradiussuite une chute des a hauteur chez une femme de30ans","c":true},{"l":"D","t":"Une fracture de la diaphyse humérale suite à une chute d’une echelle chez une femme de50ans","c":false},{"l":"E","t":"Une fracture du bassin suite aun traumatisme banal, chez une femme de 45 ans aux antécédents de polyarthrite rhumatoide","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(491, 17, 'Traumatologie', 'Bassin et cotyle', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'En cas de suspicion le LCH, la radiographie du bassin:', '[{"l":"A","t":"Ne doit pas se faire avant l’âge de 6 mois","c":false},{"l":"B","t":"Ne permet pas de mettre en évidence une dysplasie cotyloïdienne avant l’âge de 4 mois","c":true},{"l":"C","t":"Est obligatoire pour le suivi sous traitement d’une LCH","c":true},{"l":"D","t":"Doit obéir à des règles strictes de symétrie pour pouvoir interpréter les résultats radiographiques","c":true},{"l":"E","t":"La présence d’un U radiologique signe que la tête fémorale a habité le cotyle.","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(492, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le traitement orthopédique par traction d’une luxation de la hanche:', '[{"l":"A","t":"Débute par la phase d’abaissement de la tête fémorale","c":true},{"l":"B","t":"La 2ème phase est la phase de recentrage de la tête fémorale en face du cotyle","c":true},{"l":"C","t":"La 3ème phase et la phase de stabilisation de la hanche","c":false},{"l":"D","t":"La stabilisation se fait par un plâtre pelvi-pédieux","c":true},{"l":"E","t":"La stabilisation peut être faite par une culotte d’abduction","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(493, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'A propos de la structure de l’appareil locomoteur, marquez la seule réponse exact', '[{"l":"A","t":"Une diarthrose est une articulation synovial","c":true},{"l":"B","t":"La symphyse pubienne est une diarthros","c":false},{"l":"C","t":"La couche sériée du cartilage de croissance est la zone la plus fragile de ce cartilag","c":false},{"l":"D","t":"Le tendon s’insère dans un os sans fibrocartilag","c":false},{"l":"E","t":"Le tendon d’Achille est le plus puissant des tendons et ne se rompt quasi jamais.","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(494, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi les complications des fractures de la paroi postérieure du cotyle, il peut y avoir:', '[{"l":"A","t":"Une irréductibilité de la luxation postérieure lorsqu’elle existe","c":true},{"l":"B","t":"Une fracture du col du fémur","c":true},{"l":"C","t":"Une paralysie sciatique","c":true},{"l":"D","t":"Une coxarthrose post-traumatique","c":true},{"l":"E","t":"Des ossifications péri-articulaires","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(495, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Les fractures du bassin sont liées à l’architecture des os. Parmi les propositions suivantes, laquelle ou lesquelles est (sont) exacte(s)?', '[{"l":"A","t":"Les zones de faiblesse postérieures sont les trous sacrés et l’articulation sacro-iliaque","c":true},{"l":"B","t":"Le contour du trou obturateur constitue un anneau de résistance antérieur rarement rompu","c":false},{"l":"C","t":"La symphyse pubienne est une articulation lâche, facilement distendue","c":false},{"l":"D","t":"Les colonnes antérieure et postérieure répartissent les forces imposées par le poids","c":true},{"l":"E","t":"La paroi postérieure du cotyle est plus développée que sa paroi antérieure","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(496, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi ces complications, quelles sont celles qu’on peut rattacher à une luxation postérieure de la hanche:', '[{"l":"A","t":"Fracture de la paroi postérieure du cotyle","c":true},{"l":"B","t":"Fracture de la tête fémorale","c":true},{"l":"C","t":"Ostéonécrose de la tête fémorale","c":true},{"l":"D","t":"Lésion du nerf sciatique","c":true},{"l":"E","t":"Toutes les réponses sont fausses","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(497, 33, 'Traumatologie', 'Palette humérale et coude', NULL, false, true, 'Quel élément anatomique peut être lésé au cours d’une fracture de l’épicondyle médial de la palette humérale:', '[{"l":"A","t":"L’artère ulnaire","c":false},{"l":"B","t":"Nerf ulnaire.","c":true},{"l":"C","t":"Nerf médian.","c":false},{"l":"D","t":"Nerf radial","c":false},{"l":"E","t":"Artère radiale","c":false}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(498, 33, 'Traumatologie', 'Palette humérale et coude', NULL, false, true, 'Dans les fractures de la palette humérale chez l’adulte, le type CI selon MULLER et ALGOWER correspond à: (cochez la ou les réponses justes)', '[{"l":"A","t":"Une fracture extra articulaire.","c":false},{"l":"B","t":"Une fracture sus et intercondylienne simple.","c":true},{"l":"C","t":"Une fracture unicondylienne.","c":false},{"l":"D","t":"Une fracture articulaire totale.","c":true},{"l":"E","t":"Une fracture sus et intercondylienne comminutive.","c":false}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(499, 33, 'Traumatologie', 'Palette humérale et coude', NULL, false, true, 'Indiquez, parmi les suivantes, la ou les proposition(s) exacte(s) concemant les fractures du condyle médial de la palette humérale chez l’adulte:', '[{"l":"A","t":"Ce sont des fractures articulaires.","c":true},{"l":"B","t":"Le trait de fracture est horizontal,","c":false},{"l":"C","t":"Le trait détache un fragment emportant l’épicondyle médial avec la joue médiale de la trochlée humérale.","c":true},{"l":"D","t":"Ce sont des fractures du groupe C selon MÜLLER et ALLGOWER","c":false},{"l":"E","t":"Le déplacement se fait en translation médiale","c":true}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(500, 32, 'Traumatologie', 'Fracture de l’humérus', NULL, false, true, 'L’examen clinique d’une fracture de l’épicondyle médial de la palette humérale compliquée d’une paralysie du nerf ulnaire (cubital) retrouve:', '[{"l":"A","t":"Un déficit de l’extension du poignet et des doigts.","c":false},{"l":"B","t":"Une anesthésie de la pulpe de l’index.","c":false},{"l":"C","t":"Un déficit de l’écartement et rapprochement des doigts.","c":true},{"l":"D","t":"Une anesthésie de la face dorsale de la 16 commissure de la main. E. Une anesthésie de la pulpe de l’auriculaire.","c":false}]'::jsonb, NULL, '["Annales classées","Rattrapage OTR promo 2019"]'::jsonb),
(501, 33, 'Traumatologie', 'Palette humérale et coude', NULL, false, true, 'Indiquez, parmi les réponses suivantes, la ou les proposition(s) exacte(s) concernant les fractures parcellaires de la palette humérale chez l’adulte: (Cochez la ou les réponses justes)', '[{"l":"A","t":"Ce sont des fractures extra articulaires.","c":true},{"l":"B","t":"Le trait de fracture est horizontal.","c":false},{"l":"C","t":"Le trait sépare l’épicondyle médial ou latéral.","c":true},{"l":"D","t":"Ce sont des fractures du groupe C selon MÜLLER et ALLGOWER.","c":false},{"l":"E","t":"Le déplacement se fait en chevauchement.","c":false}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(502, 33, 'Traumatologie', 'Palette humérale et coude', NULL, false, true, 'Le bilan radiologique d’une fracture déplacée de la palette humérale comporte: (Cochez la ou les réponses justes)', '[{"l":"A","t":"Echographie à la recherche d’une hémarthrose.","c":false},{"l":"B","t":"Radiologie standard du coude de face et de profil.","c":true},{"l":"C","t":"Eléctro-myographie à la recherche d’une complication nerveuse.","c":false},{"l":"D","t":"Scanner du coude.","c":true},{"l":"E","t":"IRM du coude.","c":false}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(503, 41, 'Traumatologie', 'Luxation du coude', NULL, false, true, 'Le syndrome d’ESSEX LOPRESSTI correspond à: (cochez la ou les réponses justes)', '[{"l":"A","t":"Fracture de l’extrémité supérieure des 02 de l’avant-bras associée à une luxation du coude.","c":false},{"l":"B","t":"Fracture de la tête radiale avec lésion du ligament collatérale latéral du coude,","c":false},{"l":"C","t":"Fracture de la tête radiale associée à une lésion de la membrane interosseuse de l’avant-bras","c":true},{"l":"D","t":"Fracture luxation de la tête radiale,","c":false},{"l":"E","t":"Luxation trans-olécranienne (luxation antérieure conjointe du coude).","c":false}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(504, 33, 'Traumatologie', 'Palette humérale et coude', NULL, false, true, 'Les fractures de type 2 de l’olécrane selon MERLE D’AUBIGNE:', '[{"l":"A","t":"Surviennent après un traumatisme indirect.","c":false},{"l":"B","t":"Le trait est simple et intéresse la grande cavité sigmoide","c":true},{"l":"C","t":"Le traitement est chirurgical lorsqu’elles sont déplacées.","c":true},{"l":"D","t":"Le trait est extra-articulaire,","c":false},{"l":"E","t":"Sont des fractures comminutives.","c":false}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(505, 41, 'Traumatologie', 'Luxation du coude', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, true, 'Les fractures de la tête radiale de types 3 selon MASON sont:', '[{"l":"A","t":"Des fractures simples déplacées.","c":false},{"l":"B","t":"Des fractures comminutives.","c":true},{"l":"C","t":"Des fractures simples non déplacées","c":false},{"l":"D","t":"Des fractures de la tête radiale associées à une luxation du coude.","c":false},{"l":"E","t":"Des fractures de la tête radiale associées à une fracture de l’olécrane.","c":false}]'::jsonb, NULL, '["Annales classées","EMD section B promo 2019 (22/02/2024)","Rattrapage OTR promo 2019"]'::jsonb),
(506, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, true, 'Les complications des fractures de la tête radiale sont:', '[{"l":"A","t":"Nécrose de la tête radiale.","c":true},{"l":"B","t":"Pseudarthrose.","c":false},{"l":"C","t":"Raideur de la prono-supination.","c":true},{"l":"D","t":"Paralysie du nerf ulnaire.","c":false},{"l":"E","t":"Arthrose.","c":true}]'::jsonb, NULL, '["Annales classées","Rattrapage OTR promo 2019"]'::jsonb),
(507, 33, 'Traumatologie', 'Palette humérale et coude', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, true, 'Le traumatisme dans la fracture de l’extrémité proximal du radius est: (Cochez la ou les réponses justes)', '[{"l":"A","t":"Le plus souvent choc direct.","c":false},{"l":"B","t":"Le plus souvent choc indirect.","c":true},{"l":"C","t":"Mécanisme coude en pronation extension.","c":true},{"l":"D","t":"Mécanisme coude en supination flexion.","c":false},{"l":"E","t":"Toutes les réponses sont fausses.","c":false}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(508, 29, 'Traumatologie', 'Algoneurodystrophie', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, true, 'Les complications de la fracture de la tête radiale sont: (La ou les réponses justes)', '[{"l":"A","t":"Déplacement secondaire.","c":true},{"l":"B","t":"Syndrome douloureux régional complexe.","c":true},{"l":"C","t":"Raideur en prono-supination.","c":true},{"l":"D","t":"Cal vicieux et arthrose.","c":true},{"l":"E","t":"Toutes les réponses sont fausses.","c":false}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(509, 41, 'Traumatologie', 'Luxation du coude', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Concernant la luxation du coude (cochez la ou les réponses justes)', '[{"l":"A","t":"Elle se produit fréquemment chez le sujet jeune surtout à la suite d’un accident sportif.","c":false},{"l":"B","t":"Les trois repères osseux du coude sont conservés en flexion et en extension.","c":false},{"l":"C","t":"L’ecchymose latéralisée devra faire suspecter une fracture associée de l’épitrochiée ou de l’épicondyle ou une lésion ligamentaire latérale.","c":false},{"l":"D","t":"La réduction d’urgence de la luxation du coude se fait sous anesthésie locale.","c":false},{"l":"E","t":"L’ostéome est une complication secondaire fréquente de la luxation du coude.","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(510, 8, 'Traumatologie', 'Polytraumatisme', NULL, false, true, 'Chez un polytraumatisé comateux adulte sans hémorragie extériorisée Importante, une hypotension artérielle en dessous de 7 avec une tachycardie au-dessus de 120 peut être due à:', '[{"l":"A","t":"Un hématome extradural","c":false},{"l":"B","t":"Un volet costal","c":false},{"l":"C","t":"Un hémopéritoine","c":true},{"l":"D","t":"Une fracture du fémur","c":true},{"l":"E","t":"Un choc vagal","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022","Banque de QCM OTR","Banque de QCM OTR p.11"]'::jsonb),
(511, 7, 'Traumatologie', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Comment allez-vous transporter idéalement un polytraumatisé qui a un traumatisme crânien un voler thoracique gauche:', '[{"l":"A","t":"En décubitus dorsal 1/2 assis","c":false},{"l":"B","t":"En position latérale de sécurité gauche","c":false},{"l":"C","t":"Avec alignement axial tête-cou-tronc","c":true},{"l":"D","t":"En assistance respiratoire","c":true},{"l":"E","t":"Tête basse, jambes surélevées et bandées pour lutter contre l’hypotension","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(512, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, true, true, 'Le polytraumatisme: (la ou les réponses justes)', '[{"l":"A","t":"Atteinte de plusieurs étages anatomiques.","c":true},{"l":"B","t":"Fracture fermée du fémur.","c":false},{"l":"C","t":"Fracture ouverte des deux os de la jambe.","c":false},{"l":"D","t":"Luxation récidivante de l’épaule.","c":false},{"l":"E","t":"Traumatisme crânien","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(513, 26, 'Traumatologie', 'Polytraumatisme', NULL, false, true, 'Devant un polytraumatisé, une luxation postérieure de la hanche doit être suspectée devant: (La ou les réponses justes)', '[{"l":"A","t":"un blessé inconscient","c":true},{"l":"B","t":"une attitude en rotation externe adduction du membre inférieur","c":false},{"l":"C","t":"une attitude en rotation interne adduction du membre inférieur","c":true},{"l":"D","t":"une attitude en abduction rotation interne du membre inférieur","c":false},{"l":"E","t":"une attitude en raccourcissement abduction du membre","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(514, 18, 'Traumatologie', 'Amputations des membres', NULL, false, true, 'Chez un polytraumatisé porteur d’une fracture récente de la diaphyse du fémur immobilisée en traction, une embolie graisseuse doit être suspectée devant:', '[{"l":"A","t":"Elevation de la pa CO2","c":false},{"l":"B","t":"Baisse de la pa O2","c":true},{"l":"C","t":"Présence de pétechies sur la paroi thoracique","c":true},{"l":"D","t":"Pétéchies au fond d’oeil","c":true},{"l":"E","t":"Image d’amputation à la scintigraphie pulmonaire en ventilation perfusion","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(515, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', NULL, false, true, 'Le bilan radiographique d’une fracture du cotyle au décours d’un polytraumatisme doit comporter:', '[{"l":"A","t":"Bassin face","c":true},{"l":"B","t":"3/4 obturateur","c":true},{"l":"C","t":"3/4 alaire","c":true},{"l":"D","t":"Faux profil de la hanche","c":false},{"l":"E","t":"Urographie intra-veineuse","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(516, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', NULL, false, true, ': Est considéré comme polytraumatisé: (cochez les réponses justes)', '[{"l":"A","t":"Un patient qui a une fracture des deux jambes après une chute dans un match de football","c":false},{"l":"B","t":"Un patient heurté par une voiture sur l’autoroute et dont l’examen initial trouve une déformation isolée de la jambe gauche","c":true},{"l":"C","t":"Un patient défénestré (chute du 3ème étage) mais dont l’examen clinique initial semble normal","c":true},{"l":"D","t":"Un accidenté de la voie publique dont le bilan lésionnel complet à l’hôpital montre une fracture de la 3ème et 4ème côtes droites et une fracture du bassin","c":true},{"l":"E","t":"Un patient qui a eu un coup de poing sur le visage (rixe) et qui devient somnolant","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(517, 8, 'Traumatologie', 'Polytraumatisme', NULL, false, true, 'Après le bilan clinique complet d’un polytraumatisé thoraco-abdominal, quelle est la technique qui fournit le plus grand nombre de données lésionnelles ?', '[{"l":"A","t":"Échographie abdominale","c":false},{"l":"B","t":"Radiographie d’abdomen et de thorax","c":false},{"l":"C","t":"Scanographie thoraco-abominale","c":true},{"l":"D","t":"Angiographie numérisée par voie veineuse","c":false},{"l":"E","t":"Ponction abdominale sous guidage échographique","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(518, 8, 'Traumatologie', 'Polytraumatisme', NULL, false, true, 'Quelles radiographies faut-il demander systématiquement chez tout polytraumatisé ?: (cochez les réponses justes)', '[{"l":"A","t":"Thorax de face","c":true},{"l":"B","t":"Bassin de face","c":true},{"l":"C","t":"ASP debout de face","c":false},{"l":"D","t":"Crâne face et profil","c":false},{"l":"E","t":"Rachis cervical face et profil","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(519, 7, 'Traumatologie', 'Complication de l’immobilité et décubitus', NULL, false, true, '6- Comment allez-vous transporter idéalement un polytraumatisé qui a un traumatisme crânien avec coma et un volet thoracique gauche: (cochez les réponses justes)', '[{"l":"A","t":"En décubitus dorsal demi-assis","c":false},{"l":"B","t":"En position latérale de sécurité gauche","c":false},{"l":"C","t":"Avec alignement axial tête-cou-tronc","c":true},{"l":"D","t":"En assistance respiratoire","c":true},{"l":"E","t":"Tête basse, jambes surélevées et bandées pour lutter contre l’hypotension","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(520, 8, 'Traumatologie', 'Polytraumatisme', NULL, false, true, 'Chez un patient polytraumatisé, agité, sans atteinte viscérale apparente à l’examen clinique, sans état de choc, quelle est la conduite à tenir ? (cochez les réponses justes)', '[{"l":"A","t":"Surveillance seule","c":false},{"l":"B","t":"TDM crâne","c":true},{"l":"C","t":"Échographie abdominale","c":true},{"l":"D","t":"Scintigraphie osseuse","c":false},{"l":"E","t":"Radiographie pulmonaire","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(521, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Les fractures diaphysaires des deux os de l’avant-bras chez l’adulte: (cochez la ou les réponses justes)', '[{"l":"A","t":"Relevé exclusivement d’un traitement chirurgical","c":true},{"l":"B","t":"Consolide dans tous les cas","c":false},{"l":"C","t":"Le syndrome de Volkmann peut complique ce type de fracture","c":true},{"l":"D","t":"La lésion du nerf circonflexe est une complication fréquente","c":false},{"l":"E","t":"L’ostéosynthèse par plaques vissées est la méthode habituelle","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
