(552, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'La fracture du scaphoïde carpien est (cochez les réponses justes)', '[{"l":"A","t":"La fracture la plus rare des fractures du carpe","c":false},{"l":"B","t":"Survient suite a un traumatisme direct","c":false},{"l":"C","t":"Le traitement est toujours chirurgical","c":false},{"l":"D","t":"Les fractures proximales peuvent évoluer vers l’ostéonécrose","c":true},{"l":"E","t":"La vascularisation du scaphoïde est à artère unique rétrograde","c":true}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(553, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'La fracture du scaphoïde carpien est (cocher la ou les réponses fausses):', '[{"l":"A","t":"Le diagnostic peut se faire au stade de pseudarthrose","c":false},{"l":"B","t":"Une radio de poignet et pour diagnostic","c":true},{"l":"C","t":"L’évolution défavorable put se faire vers l’arthrose du poignet.","c":false},{"l":"D","t":"en cas de traitement orthopédique le gant plat doit libérer la métacarpo-phalangienne du pouce","c":true},{"l":"E","t":"les fractures proximale doivent être traitées chirurgicalement.","c":false}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(554, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'Les fractures du scaphoïde carpien présentent les caractéristiques suivantes sauf une laquelle: (Cochez la réponse juste)', '[{"l":"A","t":"La fracture du scaphoïde carpien est la lésion la plus fréquente au niveau du carpe.","c":false},{"l":"B","t":"la vascularisation de sa partie proximale est précaire.","c":false},{"l":"C","t":"Le diagnostic peut poser un problème initialement d’où l’intérêt de demander des clichés spécifiques, revoir le patient après 15 jours du traumatisme avec de nouveaux clichés ou un scanner.","c":false},{"l":"D","t":"Certaines fractures non déplacées peuvent être traitées par une manchette type scaphoïde.","c":false},{"l":"E","t":"Une radiographie normale au début élimine formellement la présence de fracture.","c":true}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(555, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'Parmi les fractures ci-après, indiquez quelle est celle qui NE se complique PAS classiquement de nécrose osseuse: (1 bonne réponse)', '[{"l":"A","t":"La fracture du col de l’humérus","c":false},{"l":"B","t":"La fracture du scaphoïde carpien","c":false},{"l":"C","t":"La fracture sous-capitale du fémur","c":false},{"l":"D","t":"La fracture sous-trochantérienne du fémur","c":true},{"l":"E","t":"La fracture du col de l’astragale","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(556, 29, 'Traumatologie', 'Algoneurodystrophie', NULL, false, true, 'Le diagnostic positif du syndrome douloureux régional complexe repose sur un faisceau d’arguments:', '[{"l":"A","t":"Tableau clinique évocateur (troubles vasomoteurs, raideur)","c":true},{"l":"B","t":"Contexte étiologique favorisant (traumatisme, immobilisation)","c":true},{"l":"C","t":"Déminéralisation osseuse, avec érosion des surfaces articulaires","c":false},{"l":"D","t":"Hypofixation scintigraphique","c":false},{"l":"E","t":"La VS et la CRP sont normales","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
