(573, 34, 'Rhumatologie', 'Sciatique et rachis médical', NULL, false, true, 'Parmi les signes cliniques suivants, quels sont ceux qui se rapportent à une sciatique S1 ?', '[{"l":"A","t":"Radiculalgies irradiant à la face postérieure de la cuisse,","c":true},{"l":"B","t":"Abolition du réflexe achilléen","c":false},{"l":"C","t":"Signe de Lasègue","c":true},{"l":"D","t":"Abolition du reflexe rotulien","c":false},{"l":"E","t":"Déficit extension du gros orteil","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(574, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, true, true, 'Parmi les propositions suivantes concernant la lombosciatique commune par hernie discale: Les RF(s)', '[{"l":"A","t":"L’Interrogatoire est essentiel et permet le diagnostic positif de sciatique","c":false},{"l":"B","t":"La douleur est mécanique augmentant à l’effort et la station debout prolongée","c":false},{"l":"C","t":"L’atteinte du reflexe achilléen traduit avec certitude une souffrance de L5","c":true},{"l":"D","t":"La pratique de radiographie n’est pas systématique mais doit être stratégique","c":false},{"l":"E","t":"Un Lasègue serré est prédictif de l’évolution défavorable de la sciatique","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
