(577, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Parmi ces propositions concernant la sciatique commune par hernie discale, laquelle est fausse ? (Citer la réponse fausse)', '[{"l":"A","t":"Topographie mono radiculaire L5 ou S1","c":false},{"l":"B","t":"Rythme inflammatoire","c":true},{"l":"C","t":"Manœuvre de Lasègue est positif","c":false},{"l":"D","t":"Déclencher par la station debout prolongée et la porte de charge lourdes","c":false},{"l":"E","t":"Impulsive à la toux","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(578, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Devant une lombosciatique commune par hernie discale, l’indication opératoire se pose devant (citez la réponse fausse)', '[{"l":"A","t":"Une sciatique hyperalgique","c":false},{"l":"B","t":"Un syndrome de la queue-de-cheval","c":false},{"l":"C","t":"Un déficit moteur (testing musculaire inférieur à 4)","c":false},{"l":"D","t":"Après échec un traitement médical au-delà de 6 à 8 semaines.","c":false},{"l":"E","t":"Manœuvre de Lasègue positif à 90°","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
