(581, 34, 'Rhumatologie', 'Sciatique et rachis médical', NULL, false, true, 'Une radiographie standard du rachis lombaire montre un pincement L4-L5 avec un fou des plateaux vertébraux de part et d’autre. Cet aspect correspond à:', '[{"l":"A","t":"Une fracture des deux vertèbres L4 et L5","c":false},{"l":"B","t":"Une compression radiculaire par hernie discale","c":false},{"l":"C","t":"Une spondylite de LS","c":false},{"l":"D","t":"Une spondylodiscite L4-L5","c":true},{"l":"E","t":"Une spondylite de Romanus","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
